// ── 图标解析（后端返回 lucide 图标名字符串）────────────────
const ICON_MAP: Record<string, React.ComponentType<{ className?: string }>> = {
  Bot,
  Wrench,
  Terminal,
  Cpu,
  Package,
  Boxes,
}

export function ToolIcon({ name, className }: { name?: string; className?: string }) {
  const Cmp = (name && ICON_MAP[name]) || Bot
  return <Cmp className={className} />
}

// ── Badge ────────────────────────────────────────────────
type BadgeTone = 'green' | 'blue' | 'red' | 'gray' | 'amber'

const BADGE_TONES: Record<BadgeTone, string> = {
  green: 'bg-green-500/15 text-green-600 dark:text-green-400 border-green-500/30',
  blue: 'bg-blue-500/15 text-blue-600 dark:text-blue-400 border-blue-500/30',
  red: 'bg-red-500/15 text-red-600 dark:text-red-400 border-red-500/30',
  gray: 'bg-muted text-muted-foreground border-border',
  amber: 'bg-amber-500/15 text-amber-600 dark:text-amber-400 border-amber-500/30',
}

export function Badge({
  tone = 'gray',
  className,
  children,
}: {
  tone?: BadgeTone
  className?: string
  children: ReactNode
}) {
  return (
    <span
      className={cn(
        'inline-flex items-center gap-1 rounded-md border px-2 py-0.5 text-xs font-medium',
        BADGE_TONES[tone],
        className,
      )}
    >
      {children}
    </span>
  )
}

// ── 状态徽标 ─────────────────────────────────────────────
const STATUS_META: Record<string, { label: string; tone: BadgeTone }> = {
  installed: { label: '已安装', tone: 'green' },
  installing: { label: '安装中', tone: 'blue' },
  failed: { label: '安装失败', tone: 'red' },
  uninstalled: { label: '未安装', tone: 'gray' },
  not_installed: { label: '未安装', tone: 'gray' },
}

export function StatusBadge({ status }: { status: ToolStatus | string }) {
  const meta = STATUS_META[status] || { label: status, tone: 'gray' as BadgeTone }
  return (
    <Badge tone={meta.tone}>
      {status === 'installing' && <Loader2 className="h-3 w-3 animate-spin" />}
      {meta.label}
    </Badge>
  )
}

// ── 健康状态圆点 ─────────────────────────────────────────
